--
-- Table structure for table `sample`
--

DROP TABLE IF EXISTS `sample`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sample` (
  `SampleId` int NOT NULL AUTO_INCREMENT,
  `StationId` int NOT NULL,
  `SampleDate` date DEFAULT NULL,
  `SampleTime` time DEFAULT NULL,
  `TotalDepth` varchar(50) DEFAULT NULL,
  `UpperPycnocline` varchar(50) DEFAULT NULL,
  `LowerPycnocline` varchar(50) DEFAULT NULL,
  `Depth` int DEFAULT NULL,
  `Layer` varchar(50) DEFAULT NULL,
  `SampleType` varchar(100) DEFAULT NULL,
  `SampleReplicateType` varchar(100) DEFAULT NULL,
  PRIMARY KEY (`SampleId`),
  KEY `StationId` (`StationId`),
